1	-- 多语种段落修订与发布快照 schema（H2 MySQL 兼容模式）。
2	-- 所有时间字段为数据库默认时区时间戳；版本号均从 1（文档发布版本从 0）开始单调递增。
3	
4	CREATE TABLE IF NOT EXISTS document (
5	    document_id BIGINT AUTO_INCREMENT PRIMARY KEY,
6	    target_languages VARCHAR(255) NOT NULL,
7	    draft_version INT NOT NULL,
8	    published_version INT NOT NULL,
9	    term_version INT NOT NULL,
10	    created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP
11	);
12	COMMENT ON TABLE document IS '文档：全局唯一 documentId，含 1~5 种目标语言及草稿/发布/术语版本';
13	COMMENT ON COLUMN document.document_id IS '全局唯一文档 ID，自增';
14	COMMENT ON COLUMN document.target_languages IS '目标语言列表，逗号分隔的小写语言码，1~5 种';
15	COMMENT ON COLUMN document.draft_version IS '文档草稿版本，从 1 开始；增段落或修改源文/译文/术语时加一';
16	COMMENT ON COLUMN document.published_version IS '已发布版本号，从 0 开始，每次成功发布加一';
17	COMMENT ON COLUMN document.term_version IS '当前术语版本，从 0 开始（0 表示尚未建立术语版本），每次新增术语版本加一';
18	COMMENT ON COLUMN document.created_at IS '创建时间，数据库默认时区';
19	
20	CREATE TABLE IF NOT EXISTS segment (
21	    document_id BIGINT NOT NULL,
22	    segment_id VARCHAR(64) NOT NULL,
23	    source_text LONGTEXT NOT NULL,
24	    source_version INT NOT NULL,
25	    PRIMARY KEY (document_id, segment_id)
26	);
27	COMMENT ON TABLE segment IS '段落：文档内唯一 segmentId，含源文及源文版本';
28	COMMENT ON COLUMN segment.document_id IS '所属文档 ID';
29	COMMENT ON COLUMN segment.segment_id IS '文档内唯一段落 ID';
30	COMMENT ON COLUMN segment.source_text IS '源文正文，UTF-8';
31	COMMENT ON COLUMN segment.source_version IS '源文版本，从 1 开始，每次源文修订加一';
32	
33	CREATE TABLE IF NOT EXISTS translation (
34	    document_id BIGINT NOT NULL,
35	    segment_id VARCHAR(64) NOT NULL,
36	    language VARCHAR(16) NOT NULL,
37	    content LONGTEXT NOT NULL,
38	    author VARCHAR(128) NOT NULL,
39	    source_version INT NOT NULL,
40	    translation_version INT NOT NULL,
41	    term_version INT NOT NULL,
42	    updated_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,
43	    PRIMARY KEY (document_id, segment_id, language)
44	);
45	COMMENT ON TABLE translation IS '译文：按段落与语言唯一，保存正文、作者、所依据源文版本、绑定术语版本及递增译文版本';
46	COMMENT ON COLUMN translation.document_id IS '所属文档 ID';
47	COMMENT ON COLUMN translation.segment_id IS '所属段落 ID';
48	COMMENT ON COLUMN translation.language IS '目标语言码，小写';
49	COMMENT ON COLUMN translation.content IS '译文正文，UTF-8';
50	COMMENT ON COLUMN translation.author IS '译文作者，取提交时 X-Actor-Id';
51	COMMENT ON COLUMN translation.source_version IS '译文所依据的源文版本；提交时必须等于当前源文版本';
52	COMMENT ON COLUMN translation.translation_version IS '译文版本，从 1 开始，每次重新提交加一';
53	COMMENT ON COLUMN translation.term_version IS '译文提交时绑定的术语版本；不等于当前术语版本时视为术语过期';
54	COMMENT ON COLUMN translation.updated_at IS '最近提交时间，数据库默认时区';
55	
56	CREATE TABLE IF NOT EXISTS approval (
57	    document_id BIGINT NOT NULL,
58	    segment_id VARCHAR(64) NOT NULL,
59	    language VARCHAR(16) NOT NULL,
60	    reviewer VARCHAR(128) NOT NULL,
61	    source_version INT NOT NULL,
62	    translation_version INT NOT NULL,
63	    approved_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,
64	    PRIMARY KEY (document_id, segment_id, language)
65	);
66	COMMENT ON TABLE approval IS '批准：按段落与语言唯一；源文或译文版本改变后先前批准不再有效';
67	COMMENT ON COLUMN approval.document_id IS '所属文档 ID';
68	COMMENT ON COLUMN approval.segment_id IS '所属段落 ID';
69	COMMENT ON COLUMN approval.language IS '目标语言码，小写';
70	COMMENT ON COLUMN approval.reviewer IS '审核人，取批准时 X-Actor-Id，不得是译文作者';
71	COMMENT ON COLUMN approval.source_version IS '批准时的源文版本，发布校验须等于当前源文版本';
72	COMMENT ON COLUMN approval.translation_version IS '批准时的译文版本，发布校验须等于当前译文版本';
73	COMMENT ON COLUMN approval.approved_at IS '批准时间，数据库默认时区';
74	
75	CREATE TABLE IF NOT EXISTS release_snapshot (
76	    document_id BIGINT NOT NULL,
77	    published_version INT NOT NULL,
78	    snapshot_json LONGTEXT NOT NULL,
79	    created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,
80	    PRIMARY KEY (document_id, published_version)
81	);
82	COMMENT ON TABLE release_snapshot IS '发布快照：发布时原子生成的完整只读快照，JSON 序列化，不可修改';
83	COMMENT ON COLUMN release_snapshot.document_id IS '所属文档 ID';
84	COMMENT ON COLUMN release_snapshot.published_version IS '发布版本号，从 1 开始';
85	COMMENT ON COLUMN release_snapshot.snapshot_json IS '快照内容 JSON：全部段落源文及各语言译文、作者、审核人与版本号';
86	COMMENT ON COLUMN release_snapshot.created_at IS '发布时间，数据库默认时区';
87	
88	CREATE TABLE IF NOT EXISTS term_version (
89	    document_id BIGINT NOT NULL,
90	    term_version INT NOT NULL,
91	    created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,
92	    PRIMARY KEY (document_id, term_version)
93	);
94	COMMENT ON TABLE term_version IS '术语版本：每个文档从 1 开始的不可变术语快照版本，已有版本不可覆盖';
95	COMMENT ON COLUMN term_version.document_id IS '所属文档 ID';
96	COMMENT ON COLUMN term_version.term_version IS '术语版本号，从 1 开始单调递增';
97	COMMENT ON COLUMN term_version.created_at IS '版本创建时间，数据库默认时区';
98	
99	CREATE TABLE IF NOT EXISTS term_rule (
100	    document_id BIGINT NOT NULL,
101	    term_version INT NOT NULL,
102	    source_term VARCHAR(512) NOT NULL,
103	    language VARCHAR(16) NOT NULL,
104	    required_translation VARCHAR(2048) NOT NULL,
