        throw ApiException.conflict(...);
    }
    Map<String,String> fallbacks = new LinkedHashMap<>();
    for (FallbackInput input : request.fallbacks()) {
        String language = normalizeLanguage(input.language());
        String fallback = normalizeLanguage(input.fallbackLanguage());
        if (!document.targetLanguages().contains(language)) 422 "语言不在文档目标语言中"
        if (!document.targetLanguages().contains(fallback)) 422 "回退语种未登记"
        if (language.equals(fallback)) 422 "回退语种不能是自身"
        if (fallbacks.put(language, fallback) != null) 422 "重复配置"
    }
    assertAcyclic(fallbacks); // 422 on cycle — 复核该文档所有目标语种回退链无环
    repository.deleteFallbacks(documentId);
