private ResolvedTranslation resolve(SegmentRow segment, String requestedLanguage,
        Map<String, TranslationRow> translations, Map<String, ApprovalRow> approvals,
        int termVersion, Map<String,String> fallbackMap, List<String> attempted) {
    String current = requestedLanguage;
    Set<String> visited = new HashSet<>();
    while (current != null && visited.add(current)) {
        attempted.add(current);
        TranslationRow t = translations.get(key(segment.segmentId(), current));
        if (t != null && t.sourceVersion() == segment.sourceVersion() && t.termVersion() == termVersion) {
            ApprovalRow a = approvals.get(key(segment.segmentId(), current));
            if (a != null && a.translationVersion() == t.translationVersion()
                    && a.sourceVersion() == segment.sourceVersion()) {
                return new ResolvedTranslation(current, t, a);
            }
        }
        current = fallbackMap.get(current);
    }
    return null;
}
```

